import{_ as e}from"./chunks/settings-ai-assistants.ChHhagkt.js";import{c as s,Q as n,j as a,m as o}from"./chunks/framework.BqPkuuVc.js";const i="/assets/onboarding-assistant.DeA8vJXk.png",r="/assets/assistant-ask-panel.DHruGgQb.png",h="/assets/assistant-scope-info.cEYKP05c.png",b=JSON.parse('{"title":"Built-in assistant","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/built-in-assistant.md","filePath":"user/reference/built-in-assistant.md"}'),d={name:"user/reference/built-in-assistant.md"};function u(l,t,c,g,m,p){return n(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="built-in-assistant" tabindex="-1">Built-in assistant <a class="header-anchor" href="#built-in-assistant" aria-label="Permalink to &quot;Built-in assistant&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers and timing operators who want quick answers while they work.</p><p>meshO Manager can answer questions typed in your own words, right inside the app:</p><blockquote><p><em>How do I import entries?</em><em>How do I give someone a hire card?</em><em>How many people mispunched today?</em><em>Who is still out on course?</em></p></blockquote><p>The answers are written by Claude, an AI model made by Anthropic, through a meshO service on the internet. There is nothing to install and no account to create. To begin with it answers <strong>questions about using meshO Manager</strong>: nothing is sent anywhere until somebody asks a question, and then only the question and pages of the documentation. Answers about the event itself are something an organiser turns on, in the welcome tour or in <strong>Settings → <a href="./settings#ai-assistants">AI assistants</a></strong>, and it can be switched off altogether there too.</p><p>This is different from <a href="./ai-assistants-mcp">AI assistants (MCP)</a>, which connects an assistant <em>you</em> run — Claude desktop, or another app — to your event. The built-in assistant needs no setup on your side, and it can only read: it can never change your event.</p><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><p>Open <strong>Settings → <a href="./settings#ai-assistants">AI assistants</a></strong> (under <strong>System</strong>). The built-in assistant is at the top of the page; choose how much it may see:</p><table tabindex="0"><thead><tr><th>Choice</th><th>What it answers</th><th>What leaves this computer</th></tr></thead><tbody><tr><td><strong>Off</strong></td><td>Nothing. The Ask button is hidden.</td><td>Nothing.</td></tr><tr><td><strong>Questions about using meshO Manager</strong> (the default)</td><td>How to do things in meshO Manager, from the documentation that came with your version.</td><td>Your question and the documentation pages it needs. No names, times or results.</td></tr><tr><td><strong>Questions about using meshO Manager and about the open event</strong></td><td>The above, plus questions about the event you have open: results, start lists, who is still out, radio punches.</td><td>Your question, and the parts of the event needed to answer it — competitors&#39; names, clubs, times and statuses.</td></tr></tbody></table><p>The change takes effect straight away. No restart is needed.</p><p><img src="'+e+'" alt="Settings → AI assistants: the built-in assistant&#39;s choice at the top, and Connect your own assistant (MCP) below"></p><p>The welcome tour&#39;s <strong>Ask for help</strong> step offers the same choice, as the setting stands, with a note on how long questions are kept:</p><p><img src="'+i+'" alt="The welcome tour&#39;s Ask for help step: Questions about using meshO Manager (chosen), the same and about the open event, or Off, with meshO keeps each question for 30 days"></p><h2 id="ask-a-question" tabindex="-1">Ask a question <a class="header-anchor" href="#ask-a-question" aria-label="Permalink to &quot;Ask a question&quot;">​</a></h2><p>Open an event and click the <strong>Ask</strong> button in the top bar. It carries the same icon as the <strong>AI assistants</strong> settings page. Type your question and press <strong>Enter</strong>.</p><p><img src="'+r+'" alt="The Ask panel open beside an event&#39;s dashboard: the question &quot;How do I import entries?&quot;, the step &quot;Searching the documentation&quot;, and a numbered answer ending with a link to the Importing event data guide."></p><p>The answer appears as it is written. Underneath your question you can see what the assistant looked at — <em>Searching the documentation</em>, or <em>Reading the event (get_results)</em> — so you can tell where an answer came from. Answers about how to do something end with a link to the documentation page they came from; it opens in a new tab, from the copy of the documentation built into meshO Manager.</p><p>The conversation stays while the panel is open on this event, so you can ask a follow-up (&quot;and in W21?&quot;). Click the restart arrow to start again. Closing the browser tab, opening another event, or changing the setting starts a new conversation. Nothing you ask is saved to the event.</p><p>The line under <strong>Ask</strong> says what the assistant can see (<em>Answers from the documentation</em>). Its information button opens <strong>What the assistant can see</strong>, with an <strong>Also answer questions about the open event</strong> switch: it is the same setting as in <strong>Settings → <a href="./settings#ai-assistants">AI assistants</a></strong>, so turning it on here applies to every event on this computer, and a warning says what that sends.</p><p><img src="'+h+'" alt="What the assistant can see, opened from the Ask panel: answers from the documentation, the Also answer questions about the open event switch, the warning about what is sent, and a note that this is the setting under Settings → AI assistants"></p><p>Below the question box, <em>Answers are written by AI and can be wrong.</em> Before you ask, the panel suggests a few example questions to click.</p><h3 id="tell-mesho-how-an-answer-did" tabindex="-1">Tell meshO how an answer did <a class="header-anchor" href="#tell-mesho-how-an-answer-did" aria-label="Permalink to &quot;Tell meshO how an answer did&quot;">​</a></h3><p>Under each answer, <em>Was this helpful?</em> has a thumbs up and a thumbs down. A thumbs down opens <strong>What was missing? (optional)</strong>: a sentence there — &quot;it didn&#39;t say which printer&quot; — is the most useful thing you can tell meshO about an answer, because it says what the documentation should have said. Click <strong>Send</strong> to send it, or leave it empty. Both go to meshO with your question, and are kept for the same 30 days.</p><h2 id="what-it-will-and-won-t-do" tabindex="-1">What it will and won&#39;t do <a class="header-anchor" href="#what-it-will-and-won-t-do" aria-label="Permalink to &quot;What it will and won&#39;t do&quot;">​</a></h2><ul><li><strong>It only reads.</strong> It cannot change a competitor, a class, a result or anything else, and it will not offer to.</li><li><strong>It only states a number it has read.</strong> If it could not read something, it says so rather than guessing.</li><li><strong>&quot;I couldn&#39;t find that&quot; is not &quot;you can&#39;t&quot;.</strong> The assistant finds pages by the words in your question. If you call something by a different name from the documentation, it can miss the page. Ask again in other words, or look the task up in <a href="./find-a-task">Find a task</a>, which lists tasks under the ways people ask for them.</li><li><strong>It can be wrong.</strong> Answers are written by AI. Check anything that matters — a placing you are about to announce, a disqualification — against the screen it came from.</li><li><strong>Results that are being held back</strong> are visible to it, because you are the operator. It says when a class&#39;s results are <a href="./../event-setup/results-quarantine">held back</a>, so you don&#39;t pass them on by accident.</li></ul><h2 id="what-is-sent-and-where" tabindex="-1">What is sent, and where <a class="header-anchor" href="#what-is-sent-and-where" aria-label="Permalink to &quot;What is sent, and where&quot;">​</a></h2><p>When you ask a question, meshO Manager sends it to the <strong>meshO assistant service</strong> (at <code>assist.mesho.live</code>), which passes it to Anthropic to write the answer.</p><ul><li><strong>With &quot;Questions about using meshO Manager&quot;</strong>, only your question and excerpts from the documentation are sent.</li><li><strong>With &quot;…and about the open event&quot;</strong>, the parts of the event needed for the answer are sent too: competitors&#39; names, clubs, classes, card numbers, times, statuses and radio punches.</li><li><strong>Birth years and sex are never sent</strong>, under either setting. The assistant can read the event&#39;s change history, but changes to either are shown to it without their values.</li><li><strong>The meshO service keeps the text of each question for 30 days</strong>, so meshO can see what people need help with and improve the documentation. It is deleted after that. A question is kept as you typed it, so avoid typing anything private into one — a competitor&#39;s phone number, say.</li><li><strong>The answer is kept too, for a question about using meshO Manager</strong> — one asked while the assistant could only read the documentation — so meshO can check the answers it gave. <strong>An answer about your event is never kept</strong>, and nor is anything read from your event.</li><li><strong>With each question it keeps a note of how it was answered</strong>, for the same 30 days: the words the assistant searched the documentation for and how many sections each search found, the pages it read, which of the event&#39;s tools it used (by name — never what they returned), how long the answer took and what it cost, whether it was a follow-up to an earlier question, the screen you asked from (its name, such as the Download card screen), whether the event was being set up, running or finished, and the version and language of meshO Manager. A search that found nothing is how meshO finds what the documentation is missing.</li><li><strong>What you tell it about an answer</strong> — the thumbs up or down, what was missing, and which documentation page you opened from the answer (a link to any other site is recorded only as &quot;another site&quot;) — is kept with the question for the same 30 days.</li><li>It also records which installation asked, when, and how much text was involved, to keep the service within its budget.</li><li>Anthropic handles the text under its commercial terms for the Claude API.</li></ul><h2 id="no-internet" tabindex="-1">No internet? <a class="header-anchor" href="#no-internet" aria-label="Permalink to &quot;No internet?&quot;">​</a></h2><p>The assistant needs an internet connection. Without one, the panel says <em>Can&#39;t reach the assistant</em> and nothing else in meshO Manager is affected. Running the event never depends on it.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><p>Each computer has a daily allowance of questions. If it is used up the panel says so, and it resets at midnight UTC. A question that would need a very long answer, or a great many look-ups, is stopped with a message asking for something narrower — &quot;who is still out in M21E?&quot; rather than &quot;tell me everything about today&quot;.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>What to do</th></tr></thead><tbody><tr><td>No Ask button</td><td>The assistant is off. An organiser can turn it on in <strong>Settings → <a href="./settings#ai-assistants">AI assistants</a></strong>.</td></tr><tr><td><em>Can&#39;t reach the assistant</em></td><td>This computer has no internet connection, or a firewall blocks <code>assist.mesho.live</code>.</td></tr><tr><td><em>Today&#39;s assistant allowance for this computer is used up</em></td><td>Wait until midnight UTC, or use the documentation directly.</td></tr><tr><td><em>The assistant is paused</em></td><td>The service is paused for everyone. Try again later.</td></tr><tr><td>It says it can only answer questions about using meshO Manager</td><td>The setting is <strong>Questions about using meshO Manager</strong>. In <strong>Settings → AI assistants</strong>, choose the option that includes the open event.</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./find-a-task">Find a task</a>: tasks listed under the ways people ask for them</li><li><a href="./ai-assistants-mcp">AI assistants (MCP)</a> — connect an assistant of your own, which can also make changes if you allow it</li><li><a href="./settings">Settings</a></li><li><a href="./../event-setup/results-quarantine">Results quarantine</a></li></ul>',36)])])}const y=s(d,[["render",u]]);export{b as __pageData,y as default};
